<?php declare(strict_types=1); require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/auth_check.php'; require_once __DIR__.'/../includes/helpers.php'; require_login(); require_post_csrf();
$id=(int)($_POST['id']??0);try{$pdo=db();$q=$pdo->prepare('SELECT item_name FROM items WHERE id=?');$q->execute([$id]);$name=(string)$q->fetchColumn();if($name!==''){$pdo->prepare('DELETE FROM items WHERE id=?')->execute([$id]);log_activity($pdo,(int)$_SESSION['user_id'],'Menghapus barang: '.$name);flash('success','Barang berhasil dihapus.');}}catch(PDOException $e){error_log($e->getMessage());flash('error','Barang tidak dapat dihapus.');}redirect_to('/pages/items.php');
